/// <summary>
/// Outer controller class purchase order packing slip posting.
/// </summary>
class METPurchParmPackingSlipOuterController extends SrsReportRunController
{
}

Method.Source:
/// <summary>
/// Run method
/// </summary>
public void run()
{
    return;
}

/// <summary>
/// Constructs <c>METPurchParmPackingSlipOuterController</c>.
/// </summary>
/// <returns>
/// <c>METPurchParmPackingSlipOuterController</c>.
/// </returns>
public static METPurchParmPackingSlipOuterController construct()
{
    return new METPurchParmPackingSlipOuterController();
}

/// <summary>
/// Starts the process.
/// </summary>
/// <param name = "_args">
/// <c>Args</c>.
/// </param>
public static void main(Args _args)
{
    METPurchParmPackingSlipOuterController controller;

    controller = METPurchParmPackingSlipOuterController::construct();

    controller.init();
    controller.parmArgs(_args);
    controller.parmDialogCaption("@MET:METPOParmReceiptService");
    controller.startOperation();

    if (!controller.isDialogCancelled())
    {
        METPurchParmPackingSlipController innerController;

        innerController = METPurchParmPackingSlipController::construct();

        controller.initInnerController(innerController);
        innerController.parmShowDialog(false);
        innerController.parmExecutionMode(SysOperationExecutionMode::ScheduledBatch);

        innerController.startOperation();
    }

}

/// <summary>
/// Initializes <c>METPurchParmPackingSlipController</c>.
/// </summary>
/// <param name = "_innerController">
/// <c>METPurchParmPackingSlipController</c>.
/// </param>
private void initInnerController(METPurchParmPackingSlipController _innerController)
{
    METPOContinuingPermissionNoticeContract contract;
    SRSPrintDestinationSettings reportPrintDestSettings;
    METPurchParmPackingSlipContract innerContract;

    contract = this.parmReportContract().parmRdpContract() as METPOContinuingPermissionNoticeContract;
    reportPrintDestSettings = this.parmReportContract().parmPrintSettings() as SRSPrintDestinationSettings;
    innerContract = _innerController.getDataContractObject() as METPurchParmPackingSlipContract;

    innerContract.parmThreadCount(contract.parmThreadCount());
    innerContract.parmIsAutoGenerateCPNotice(contract.parmIsAutoGenerateCPNotice());
    innerContract.setPrintDestinationSettings(reportPrintDestSettings);
}

/// <summary>
/// Initialises the controller.
/// </summary>
private void init()
{
    METPOContinuingPermissionNoticeController controller =
        METPOContinuingPermissionNoticeController::construct();

    PrintMgmtDocumentType type =  PrintMgmtDocumentType::METPOContinuingPermissionNote;
    PrintMgmtReportFormat printMgmtReportFormat = PrintMgmtReportFormat::findSystem(type);

    if (!printMgmtReportFormat.RecId)
    {
        select Name from printMgmtReportFormat
            where printMgmtReportFormat.DocumentType == type;
    }

    this.parmReportName(printMgmtReportFormat.Name);
}

/// <summary>
/// method returns boolean value based on the dialog form cancelled or not
/// </summary>
/// <returns>boolean</returns>
public boolean isDialogCancelled()
{
    return dialogCanceled;
}
